using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace CyberPW.Assistant2{
 internal sealed class GradientPanel:Panel{public Color StartColor=Color.FromArgb(2,37,43),EndColor=Color.FromArgb(9,73,57),BorderColor=Theme.Gold;public bool ShowBorder;public int BorderThickness=3;public GradientPanel(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);}protected override void OnPaintBackground(PaintEventArgs e){if(ClientRectangle.Width<1||ClientRectangle.Height<1)return;using(var b=new LinearGradientBrush(ClientRectangle,StartColor,EndColor,90F))e.Graphics.FillRectangle(b,ClientRectangle);}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(ShowBorder)using(var p=new Pen(BorderColor,BorderThickness))e.Graphics.DrawRectangle(p,1,1,Width-3,Height-3);}}
 internal sealed class FramedFlowPanel:FlowLayoutPanel{public Color BorderColor=Theme.Gold;public int BorderThickness=3;public FramedFlowPanel(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);using(var p=new Pen(BorderColor,BorderThickness))e.Graphics.DrawRectangle(p,1,1,Width-3,Height-3);}}
}
